1	/**
2	 * Every job that runs a project's own commands sets that project's environment up
3	 * first.
4	 *
5	 * The failure this prevents is not a broken build. It is a build that passes for
6	 * the agent and fails in CI, on a machine the agent cannot see, which comes back
7	 * to an engineer as a defect that does not reproduce -- and `CI_RETRY_LIMIT`
8	 * spends three inferences on it before a human hears about it.
9	 *
10	 * Pinned against the generated YAML rather than the `.wac.ts`, because the
11	 * generated file is what an adopter receives and what actually runs. A fourth job
12	 * that runs project commands should fail this test until it includes the step.
13	 */
14	import { describe, expect, test } from "bun:test";
15	import { readFileSync } from "node:fs";
16	
17	const SETUP_STEP = "Run configured environment setup";
18	
19	/** The three jobs, and the step in each that runs what the project declared. */
20	const JOBS = [
21	  {
22	    workflow: "atomaton-runner",
23	    job: "run",
24	    projectCommands: "Run agent",
25	    why: "the agent's own shell, which is the environment every other one is compared against",
26	  },
27	  {
28	    workflow: "atomaton-check",
29	    job: "atomaton-check",
30	    projectCommands: "Run the configured checks",
31	    why: "the verdict a pull request merges on",
32	  },
33	  {
34	    workflow: "atomaton-deploy",
35	    job: "deploy",
36	    projectCommands: "Deploy the targets this run is for",
37	    why: "the least frequent and the most expensive to get wrong",
38	  },
39	] as const;
40	
41	interface WorkflowDocument {
42	  jobs?: Record<string, { steps?: { name?: string; run?: string }[] }>;
43	}
44	
45	function stepNames(workflow: string, job: string): string[] {
46	  const doc = Bun.YAML.parse(
47	    readFileSync(`dist/.github/workflows/${workflow}.yml`, "utf8"),
48	  ) as WorkflowDocument;
49	  const steps = doc.jobs?.[job]?.steps;
50	  expect(steps, `${workflow}.yml has no job named ${job}`).toBeDefined();
51	  return (steps ?? []).map((step) => step.name ?? "");
52	}
53	
54	describe("environment setup reaches every job that runs project commands", () => {
55	  for (const { workflow, job, projectCommands, why } of JOBS) {
56	    test(`${workflow} sets the environment up before "${projectCommands}"`, () => {
57	      const names = stepNames(workflow, job);
58	      const setup = names.indexOf(SETUP_STEP);
59	      const commands = names.indexOf(projectCommands);
60	
61	      expect(setup, `${workflow} runs ${why} without setting the environment up`).toBeGreaterThan(-1);
62	      expect(commands, `${workflow} no longer has a step named "${projectCommands}"`).toBeGreaterThan(-1);
63	      expect(
64	        setup,
65	        `in ${workflow}, setup runs after the commands that need it`,
66	      ).toBeLessThan(commands);
67	    });
68	  }
69	
70	  // Setup runs a project's commands, and a project's commands are not the place
71	  // for a credential nobody asked to expose. In the agent's run this is load
72	  // bearing -- the whole confinement rests on secrets not being in the
73	  // environment when third-party build code runs -- and in the other two it falls
74	  // out of step order. Either way, nothing should quietly add one.
75	  test("setup runs before any secret enters the environment", () => {
76	    for (const { workflow, job } of JOBS) {
77	      const names = stepNames(workflow, job);
78	      const setup = names.indexOf(SETUP_STEP);
79	      const secrets = names.indexOf("Resolve which repository secrets may reach this run");
80	      if (secrets === -1) continue;
81	      expect(setup, `${workflow} resolves secrets before running setup commands`).toBeLessThan(secrets);
82	    }
83	  });
84	});

