41	function branchRange(): string | undefined {
42	  // `atomaton-check.yml` checks out shallow, and a merge base cannot be computed
43	  // from one commit. Tolerated rather than required: a repository that is
44	  // already complete refuses to unshallow, which is not a failure.
45	  gitRun("fetch", "--quiet", "--unshallow", "origin");
46	
47	  // A pull request sets GITHUB_BASE_REF; a dispatch -- the agent path -- does
48	  // not, and falls back to the default branch, which is where their branches
49	  // start.
50	  const base = (process.env.GITHUB_BASE_REF || process.env.ATOMATON_BASE_BRANCH || "main").trim();
51	  if (gitRun("fetch", "--quiet", "origin", base).code !== 0) {
52	    log(`could not fetch ${base}; scanning nothing rather than guessing at a range`);
53	    return undefined;
54	  }
55	  const mergeBase = gitRun("merge-base", "FETCH_HEAD", "HEAD");
56	  if (mergeBase.code !== 0 || !mergeBase.stdout) {
57	    log(`no merge base with ${base}; scanning nothing rather than guessing at a range`);
58	    return undefined;
59	  }
60	  return `${mergeBase.stdout.trim()}..HEAD`;
61	}
