{"content": "/**
 * provider-credential-check.e2e.test.ts — the credential step, against the REAL
 * `atoma` binary.
 *
 * `tests/contract/provider-credential-check.test.ts` drives the step's bash with a
 * stub, which is where every branch can be reached. What a stub cannot tell is
 * whether the question this repository asks is one the core still answers: the
 * step deliberately degrades to a warning when the binary does not understand
 * `--credentials-present`, so a rename or a removal upstream would leave the check
 * silently doing nothing, with a green run and no failing test anywhere.
 *
 * So this runs the same step with the real binary and the REAL agent definitions,
 * and asserts both halves of the acceptance criterion: a missing credential stops
 * the run and names the secret, and a present one lets it continue in silence.
 *
 * Skipped when no binary is found, like the other e2e suites — `bun run test`,
 * which CI runs, does not include `tests/e2e`.
 */
import { describe, expect, test } from "bun:test";
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { AGENT_DEFINITIONS_DIR } from "../../src/domain/machinery-layout.ts";
import { hermeticEnv } from "../../src/scripts/testing/harness.ts";

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..");

/**
 * The binary to ask: the sibling checkout the other e2e suites use, an explicit
 * override, or whatever is on PATH — which is the one a runner has installed.
 */
function findAtoma(): string | undefined {
  const candidates = [
    process.env.ATOMA_BIN,
    join(REPO_ROOT, "..", "atoma/target/debug/atoma"),
    "/usr/local/bin/atoma",
  ].filter((path): path is string => Boolean(path));
  return candidates.find(existsSync);
}

const ATOMA = findAtoma();

/** One entry per `--field value` pair: what the pinned binary is expected to understand. */
const CREDENTIAL_FLAG_SUPPORTED = ATOMA !== undefined;

describe.skipIf(!CREDENTIAL_FLAG_SUPPORTED)("provider credential check against the real atoma", () => {
  const workflow = (): { steps?: { name?: string; run?: string }[] } => {
    const path = join(REPO_ROOT, "dist/.github/workflows/atomaton-runner.yml");
    expect(existsSync(path), "run `bun run synth` first").toBe(true);
    return Bun.YAML.parse(readFileSync(path, "utf8")) as { steps?: { name?: string; run?: string }[] };
  };

  /**
   * Run the generated step's own bash, with the repository's real machinery.
   *
   * The agent definition comes from `src/atomaton/agent-definitions` — the source
   * the deliverable ships — so this reads the `provider:` those definitions
   * actually declare rather than a fixture.
   */
  function runCheck(credentialsPresent: string[]) {
    const path = join(REPO_ROOT, "dist/.github/workflows/atomaton-runner.yml");
    const doc = Bun.YAML.parse(readFileSync(path, "utf8")) as {
      jobs?: { run?: { steps?: { name?: string; run?: string }[] } };
    };
    const step = doc.jobs?.run?.steps?.find((s) => s.name === "Check the resolved provider has a credential");
    expect(step?.run, "the generated workflow no longer has the credential check").toBeDefined();

    const dir = mkdtempSync(join(tmpdir(), "atomaton-credcheck-e2e-"));
    const machinery = join(dir, "machinery");
    writeFileSync(join(dir, ".keep"), "");
    try {
      const result = Bun.spawnSync({
        cmd: ["bash", "-c", `mkdir -p "${machinery}/${AGENT_DEFINITIONS_DIR}" && cp "${REPO_ROOT}/src/atomaton/agent-definitions/"*.md "${machinery}/${AGENT_DEFINITIONS_DIR}/" && ${step!.run}`],
        env: {
          ...hermeticEnv(),
          PATH: `${dirname(ATOMA!)}:${process.env.PATH ?? ""}`,
          AGENT: "engineer",
          ATOMATON_MACHINERY_ROOT: machinery,
          ATOMA_PROVIDER_IN: "",
          ...Object.fromEntries(
            ["OPENAI_API_KEY", "OPENROUTER_API_KEY", "ORCAROUTER_API_KEY", "ANTHROPIC_API_KEY", "ATOMA_COPILOT_TOKEN"].map(
              (name) => [`${name}_PRESENT`, credentialsPresent.includes(name) ? "true" : "false"],
            ),
          ),
        },
        stdout: "pipe",
        stderr: "pipe",
      });
      return {
        status: result.exitCode ?? -1,
        stdout: result.stdout.toString(),
        stderr: result.stderr.toString(),
      };
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  }

  /**
   * The provider the shipped definitions declare, and the credential that goes
   * with it — read from the definition and from the core's own output rather than
   * from a table here, which is the whole point of asking the core.
   */
  function shippedProviderCredential(): { provider: string; credential: string } {
    const definition = readFileSync(join(REPO_ROOT, AGENT_DEFINITIONS_DIR, "engineer.md"), "utf8");
    const provider = /^provider:\s*(\S+)\s*$/m.exec(definition)?.[1];
    expect(provider, "the shipped engineer definition names no provider").toBeDefined();

    // The core names the credential when it is absent, which is the answer this
    // step is built on — so the test reads it from the same place a run would.
    const absent = runCheck([]);
    const named = /Error: (\S+) is not set, and the \S+ provider authenticates with it/.exec(
      `${absent.stdout}${absent.stderr}`,
    )?.[1];
    expect(
      named,
      `the real binary did not name the credential for provider '${provider}'. Either the definition changed or the core stopped reporting it, which is the case this test exists to catch:\n${absent.stdout}${absent.stderr}`,
    ).toBeDefined();
    return { provider: provider!, credential: named! };
  }

  test("the pinned binary understands --credentials-present", () => {
    // Without this, every case below passes through the step's own "I could not
    // ask" branch and proves nothing.
    const result = runCheck([]);
    expect(result.stdout, "the step fell back to a warning, so the flag is unknown to this binary").not.toContain(
      "could not ask atoma",
    );
  });

  test("stops and names the secret when the provider's credential is absent", () => {
    const { credential } = shippedProviderCredential();
    const result = runCheck([]);

    expect(result.status, "a run with no provider credential must not continue").toBe(1);
    expect(result.stdout, "the name to add must be in the annotation, which is the run summary").toContain(
      `::error::this run's provider authenticates with ${credential}`,
    );
    expect(result.stdout).toContain("before the environment was built");
  });

  test("continues in silence when the provider's credential is there", () => {
    const { credential } = shippedProviderCredential();
    const result = runCheck([credential]);

    expect(result.status).toBe(0);
    // The core also prints its ordinary validation lines; a healthy run must not
    // grow a log block for a check that found nothing.
    expect(result.stdout, "a satisfied check must say nothing").toBe("");
    expect(result.stderr).toBe("");
  });
});
